// Anti-aliased step
float aastep(float a, float x) {
    float fw = 0.75*length(vec2(dFdx(x-a), dFdy(x-a)));
    return smoothstep(-fw, fw, x-a);
}

// Anti-aliased line of width w pixels around position x=a
float aaline(float a, float x, float w) {
    // Use an isotropic replacement for fwidth()
    float fw = 0.375*length(vec2(dFdx(x-a), dFdy(x-a)));
    return 1.0-smoothstep((w-1.0)*fw, (w+1.0)*fw, abs(x-a));
}

//
// This is a rough approximation to trochoid "Gerstner waves",
// made specifically to be easy to invert. The formal numeric
// accuracy is terrible, but the general likeness is quite good,
// the overall dynamic behavior is convincing, and the code is
// simple.
// By Stefan Gustavson 2025-01-19, released under the CC license
// CC-BY-SA-4.0 (https://creativecommons.org/licenses/by-sa/4.0/)
// ("Use freely for any purpose, but give credit and share modifications.")
//
float fakegerstner(float x, float b, out float warp, out float dfdx) {
    x = mod(x+0.5,2.0)-0.5; // Valid range for cos approximation is [-0.5,0.5]
    float flip = (x > 0.5) ? -1.0 : 1.0; // Remember sign flip for animation below
    x = (flip >= 0.0) ? x: 1.0-x; // Mirror up-slope to compute down-slope
    const float PI = 3.1415926536;
    // Input range for b is [0,1], like in the standard parametric formulation,
    // but we scale x by 1/pi and fake a cos(), so our range for b is [0,1/4].
    float bm = b*0.25;
    float A = sqrt(16.0*bm*(bm-x)+1.0); // This sub-expression is re-used 3x
    float ibm8 = 0.125/bm; // 1/(8*bm), used twice, this saves one division
    float x0 = (1.0-A)*ibm8; // Approximate position of the center of the circular motion
    warp = flip*(x0-x); // The lateral displacement of the local surface
    float f = 8.0/PI*b*sin(x0*PI); // Vertical displacement of the wave at position x
    dfdx = flip*8.0*bm*cos(PI*(A-1.0)*ibm8)/A; // The analytical derivative
    return f; // The most natural return value, although warp and dfdx are more useful
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float dx, dzdx;

    // Coordinates are -1 to 1 in x
    vec2 uv = 4.0*(fragCoord-0.5*iResolution.xy)/max(iResolution.x, iResolution.y);

    // Display all wave amplitudes, from zero (b=0) to just below breaking (b=1)
    float b = fragCoord.y / iResolution.y;

    // Just an alias, the generic name "t" reads better in the code
    float t = iTime;

    // Animate the wave at 0.5 Hz (Wavelength is 2.0 for this version)
    float x = uv.x - t;

    // Warp with some weak large-feature noise to bend the straight ridges
    vec2 dummyg;
    x += 0.0625*psrdnoise(0.5*uv-vec2(t, 0.2*t), vec2(0.0), 0.1*t, dummyg);

    // Fake the main waves
    float z = fakegerstner(x, b, dx, dzdx);

    // Add some more detail to the otherwise very boring surface
    vec2 wiggleg, wiggleg2, foamg, foamg2;
    vec2 st = vec2(uv.x + dx, uv.y); // Warped surface texture coords
    // Bumped noise waves, two terms, to add some detail to the bump map
    float wiggles = psrdnoise(vec2(8.0, 3.0)*st-vec2(2.5*t,0.0), vec2(0.0), t, wiggleg);
    wiggles += 0.4*psrdnoise(vec2(17.0, 7.0)*st-vec2(3.5*t,0.0), vec2(0.0), t*1.5, wiggleg2);
    wiggleg += 0.8*wiggleg2; // 0.4x height, 2x width: derivative is scaled by 0.8
    // Foam texture, with more foam as the waves approach breaking at b=1
    float dummy = psrdnoise(8.0*st, vec2(0.0), t*0.37, foamg);
    float foam = psrdnoise(vec2(15.0, 8.0)*st+0.2*foamg, vec2(0.0), t*0.17, foamg2);
    foam += 0.5*psrdnoise(vec2(29.0, 14.0)*st+0.2*foamg+0.13*foamg2, vec2(0.0), t*0.11, foamg2);
    foam = smoothstep(0.7-b*0.8, 1.0, foam*smoothstep(-0.2,0.7,b)); // Weird blend, I know

    // Bump the surface, with less noise detail as the waves get more pointy
    // (In reality, long ridged waves waves absorb energy from shorter waves)
    float bumpamount = 0.5; // Just eyeballed, with no consideration to physics
    vec3 waveg = vec3(dzdx, 0.0, 0.0);
    vec3 noiseg = vec3(wiggleg.x, wiggleg.y*0.375, 0.0);
    vec3 g = waveg + 0.3*(1.0-0.7*b)*noiseg; // Just an eyeballed blend
    vec3 N0 = vec3(0.0,0.0,1.0);
    vec3 N_ = g - dot(g, N0) * N0; // N_ orthogonal to N0
    vec3 N = N0 - bumpamount * N_;
    N = normalize(N);

    // Simple Phong lighting with a single local point light
    vec3 L;
    vec3 color = mix(vec3(0.1,0.1,0.6), vec3(1.0), foam);
    L.xy = vec2(4.0,2.0)*(iMouse.xy-0.5*iResolution.xy)/min(iResolution.x, iResolution.y);
    if (all(equal(iMouse.xy, vec2(0.0)))) L.xy = vec2(0.5);
    L.xy -= uv; // Local illumination (point light, not directional)
    L.z = 4.0;
    L = normalize(L);
    vec3 specularcolor = vec3(1.0); // white
    float lightA = 0.2;  // Ambient light
    float phongD = max(0.0, dot(L, N));
    float lightD = mix(phongD, 1.0, lightA);
    float lightS = max(0.0, -normalize(
        reflect(L, N)).z); // Global viewer in -z direction
    lightS = pow(lightS, 32.0);

    vec3 col = lightD * color + 0.7*lightS * specularcolor;

    fragColor = vec4(col, 1.0);
}

// psrdnoise (c) Stefan Gustavson and Ian McEwan,
// ver. 2021-12-02, published under the MIT license:
// https://github.com/stegu/psrdnoise/

float psrdnoise(vec2 x, vec2 period, float alpha, out vec2 gradient)
{
  vec2 uv = vec2(x.x+x.y*0.5, x.y);
  vec2 i0 = floor(uv), f0 = fract(uv);
  float cmp = step(f0.y, f0.x);
  vec2 o1 = vec2(cmp, 1.0-cmp);
  vec2 i1 = i0 + o1, i2 = i0 + 1.0;
  vec2 v0 = vec2(i0.x - i0.y*0.5, i0.y);
  vec2 v1 = vec2(v0.x + o1.x - o1.y*0.5, v0.y + o1.y);
  vec2 v2 = vec2(v0.x + 0.5, v0.y + 1.0);
  vec2 x0 = x - v0, x1 = x - v1, x2 = x - v2;
  vec3 iu, iv, xw, yw;
  if(any(greaterThan(period, vec2(0.0)))) {
    xw = vec3(v0.x, v1.x, v2.x);
    yw = vec3(v0.y, v1.y, v2.y);
    if(period.x > 0.0)
    xw = mod(vec3(v0.x, v1.x, v2.x), period.x);
    if(period.y > 0.0)
      yw = mod(vec3(v0.y, v1.y, v2.y), period.y);
    iu = floor(xw + 0.5*yw + 0.5); iv = floor(yw + 0.5);
  } else {
    iu = vec3(i0.x, i1.x, i2.x); iv = vec3(i0.y, i1.y, i2.y);
  }
  vec3 hash = mod(iu, 289.0);
  hash = mod((hash*51.0 + 2.0)*hash + iv, 289.0);
  hash = mod((hash*34.0 + 10.0)*hash, 289.0);
  vec3 psi = hash*0.07482 + alpha;
  vec3 gx = cos(psi); vec3 gy = sin(psi);
  vec2 g0 = vec2(gx.x, gy.x);
  vec2 g1 = vec2(gx.y, gy.y);
  vec2 g2 = vec2(gx.z, gy.z);
  vec3 w = 0.8 - vec3(dot(x0, x0), dot(x1, x1), dot(x2, x2));
  w = max(w, 0.0); vec3 w2 = w*w; vec3 w4 = w2*w2;
  vec3 gdotx = vec3(dot(g0, x0), dot(g1, x1), dot(g2, x2));
  float n = dot(w4, gdotx);
  vec3 w3 = w2*w; vec3 dw = -8.0*w3*gdotx;
  vec2 dn0 = w4.x*g0 + dw.x*x0;
  vec2 dn1 = w4.y*g1 + dw.y*x1;
  vec2 dn2 = w4.z*g2 + dw.z*x2;
  gradient = 10.9*(dn0 + dn1 + dn2);
  return 10.9*n;
}
